import 'server-only'

import type { CustomerBootstrap } from '@/src/domain/model'
import { supportedUiLocales } from '@/src/lib/i18n'
import { normalizeThemeId, type ThemeId } from '@/src/themes/catalog'
import { fetchBackendJsonOrNull } from './backend'
import { createMockBootstrap } from './mock-bootstrap'
import { applyMenuContentTranslations } from './menu-content-translations'
import { applySmartCategories } from './smart-categories'
import {
  normalizeFeatures,
  normalizeMenu,
  normalizeOrder,
  normalizePayments,
  normalizeRestaurant,
  normalizeSocial,
  normalizeServiceCharge,
  normalizeTable,
  normalizeTax,
  normalizeTheme,
  normalizeTips,
} from './normalize'

type BootstrapQuery = {
  host: string
  locale?: string | null
  tableId?: string | null
  tableNo?: string | null
  qr?: string | null
  previewTheme?: string | null
  forceDemo?: boolean
}

function safeParam(value: string | null | undefined): string | null {
  const clean = String(value || '').trim()
  if (!clean || clean === 'undefined' || clean === 'null') return null
  return /^[A-Za-z0-9_.:-]{1,128}$/.test(clean) ? clean : null
}

function localeCode(value: unknown): string {
  return String(value || 'en').trim().toLowerCase().split('-')[0] || 'en'
}

function queryString(entries: Record<string, string | null | undefined>): string {
  const params = new URLSearchParams()
  for (const [key, value] of Object.entries(entries)) if (value) params.set(key, value)
  const output = params.toString()
  return output ? `?${output}` : ''
}

function settingsLocale(settings: any): string {
  return String(settings?.default_language || settings?.data?.default_language || 'en').trim() || 'en'
}

function enabledLocales(settings: any, theme: any, fallback: string): string[] {
  const raw = theme?.pmd_v2_enabled_languages
    || theme?.data?.pmd_v2_enabled_languages
    || settings?.enabled_languages
    || settings?.data?.enabled_languages
    || settings?.locales
    || settings?.data?.locales
    || settings?.supported_languages
    || settings?.data?.supported_languages

  const list = Array.isArray(raw)
    ? raw
    : typeof raw === 'string'
      ? raw.split(',')
      : []

  const normalized = list.map(localeCode).filter(Boolean)

  // PMD_CUSTOMER_LANGUAGE_REGISTRY_R1
  // The dictionaries themselves own customer UI capability. Adding another UI
  // pack no longer requires maintaining a second hard-coded whitelist here.
  const supported = new Set(supportedUiLocales)
  const configured = normalized.filter((value: string) => supported.has(value))
  const candidates = configured.length ? configured : ['en', 'de'].filter((value) => supported.has(value))
  const fallbackBase = localeCode(fallback)
  const base = candidates.includes(fallbackBase) ? fallbackBase : (candidates[0] || 'en')

  return Array.from(new Set([base, ...candidates]))
}

export async function loadCustomerBootstrap(query: BootstrapQuery): Promise<CustomerBootstrap> {
  const host = String(query.host || 'localhost').split(',')[0].trim()
  const tableId = safeParam(query.tableId)
  const tableNo = safeParam(query.tableNo)
  const qr = safeParam(query.qr)
  const demoMode = query.forceDemo || process.env.PMD_DEMO_MODE === '1'
  const previewId = query.previewTheme ? normalizeThemeId(query.previewTheme) : null

  if (demoMode) return createMockBootstrap(previewId || 'verdant_modern', host)

  const requestOptions = { host, timeoutMs: 8000, cache: 'no-store' as RequestCache }
  const tableLookup = queryString({ table_id: tableId, table_no: tableNo, qr_code: qr })
  const draftLookup = queryString({ table_id: tableId, table_no: tableNo, qr })

  const [
    settings,
    restaurant,
    menuPayload,
    categoriesPayload,
    menuTranslationsPayload,
    themePayload,
    paymentsPayload,
    worldlineMethodsPayload,
    tablePayload,
    orderPayload,
    taxApiPayload,
    tipApiPayload,
  ] = await Promise.all([
    fetchBackendJsonOrNull<any>('/api/v1/settings', requestOptions),
    fetchBackendJsonOrNull<any>('/api/v1/restaurant', requestOptions),
    fetchBackendJsonOrNull<any>('/api/v1/menu', requestOptions),
    fetchBackendJsonOrNull<any>('/api/v1/categories', requestOptions),
    fetchBackendJsonOrNull<any>('/api/v1/menu-content-translations', requestOptions),
    fetchBackendJsonOrNull<any>('/api/v1/frontend-theme-v2', requestOptions),
    fetchBackendJsonOrNull<any>('/api/v1/payments', requestOptions),
    fetchBackendJsonOrNull<any>('/api/v1/payments/worldline/runtime-methods', requestOptions),
    tableId || tableNo || qr ? fetchBackendJsonOrNull<any>(`/api/v1/table-info${tableLookup}`, requestOptions) : Promise.resolve(null),
    tableId || tableNo || qr ? fetchBackendJsonOrNull<any>(`/api/v1/table-order-draft${draftLookup}`, requestOptions) : Promise.resolve(null),
    fetchBackendJsonOrNull<any>('/api/v1/vat-settings', requestOptions),
    fetchBackendJsonOrNull<any>('/api/v1/tip-settings', requestOptions),
  ])

  // PMD_VAT_FAST_FALLBACK_R34
  // Do not block every SSR render on the slow legacy VAT endpoint when
  // the canonical /api/v1/vat-settings endpoint already succeeded.
  const taxLegacyPayload = taxApiPayload
    ? null
    : await fetchBackendJsonOrNull<any>('/vat-settings', requestOptions)

  const resolvedThemePayload = themePayload || await fetchBackendJsonOrNull<any>('/simple-theme', requestOptions)

  if (!settings && !restaurant && !menuPayload && !resolvedThemePayload) {
    const allowMockFallback = ['1', 'true', 'yes', 'on'].includes(
      String(process.env.PMD_ALLOW_MOCK_FALLBACK || '').trim().toLowerCase(),
    )

    if (allowMockFallback) {
      return createMockBootstrap(previewId || 'verdant_modern', host)
    }

    throw new Error('PAYMYDINE_BACKEND_UNAVAILABLE')
  }

  const restaurantInfo = normalizeRestaurant(settings, restaurant)
  // PMD_RESTAURANT_NAME_AUTHORITY_R18
  // /admin/pmdsettings/restaurant saves site_name; make that setting the final
  // customer-menu display-name authority, with location name only as fallback.
  // PMD_RESTAURANT_IDENTITY_GUARD_R25
  // Legacy/template branding is never allowed to beat a tenant identity.
  const isGenericRestaurantName = (value: unknown) => {
    const clean = String(value || '').trim().replace(/\s+/g, ' ').toLowerCase()
    return !clean || ['tastyigniter', 'tasty igniter', 'default', 'paymydine restaurant'].includes(clean)
  }
  const nameCandidates = [
    settings?.pmd_restaurant_identity_name,
    settings?.data?.pmd_restaurant_identity_name,
    settings?.site_name,
    settings?.data?.site_name,
    restaurant?.name,
    restaurant?.data?.name,
  ].map((value) => String(value || '').trim())
  const hostLabel = host.split('.')[0] || 'PayMyDine'
  const adminRestaurantName = nameCandidates.find((value) => !isGenericRestaurantName(value)) || hostLabel
  restaurantInfo.name = adminRestaurantName

  // PMD_MENU_SMART_CATEGORIES_V1_FRONTEND_V2
  // Live tenant hosts use the V2 runtime on port 3002. Resolve editable smart
  // category names/order from /api/v1/categories, while preserving the existing
  // product flags and combo data from the canonical /api/v1/menu payload.
  const menu = applyMenuContentTranslations(
    applySmartCategories(
      normalizeMenu(menuPayload),
      menuPayload,
      categoriesPayload,
    ),
    menuTranslationsPayload,
  )

  // PMD_NEW_TENANT_SETUP_SPLASH_V2
  // Frontend V2 replaced the legacy customer app that rendered TenantSetupSplash.
  // Carry the canonical /api/v1/menu setup flag into V2 without guessing from a
  // failed/partial fetch. Missing setup metadata fails safe as configured=true so
  // an active restaurant never receives the owner setup CTA by accident.
  const menuData = menuPayload && typeof menuPayload === 'object'
    ? ((menuPayload as any).data && typeof (menuPayload as any).data === 'object'
      ? (menuPayload as any).data
      : menuPayload as any)
    : null
  const rawSetup = menuData?.setup_status && typeof menuData.setup_status === 'object'
    ? menuData.setup_status
    : null
  const frontendConfigured = typeof menuData?.is_frontend_configured === 'boolean'
    ? menuData.is_frontend_configured
    : true
  const setupStatus = rawSetup
    ? {
        hasCategories: rawSetup.has_categories === true,
        hasMenuItems: rawSetup.has_menu_items === true,
        hasLogo: rawSetup.has_logo === true,
        hasCustomSettings: rawSetup.has_custom_settings === true,
      }
    : null

  const theme = normalizeTheme(resolvedThemePayload, previewId)
  const table = normalizeTable(tablePayload, { tableId, tableNo, qr })

  // PMD_WORLDLINE_RUNTIME_ENTITLEMENT_R2
  // The Payments admin row expresses merchant intent, but Worldline's live
  // product-discovery response is the runtime authority for what that exact
  // merchant/country/currency can actually offer. Fail closed: if discovery
  // fails, Worldline-assigned methods are not exposed to the guest UI.
  const basePaymentMethods = normalizePayments(paymentsPayload)
  const worldlineDiscoveryOk = worldlineMethodsPayload?.success === true && Array.isArray(worldlineMethodsPayload?.methods)
  const worldlinePaymentMethods = worldlineDiscoveryOk
    ? normalizePayments(worldlineMethodsPayload.methods)
    : []
  const worldlineAvailableCodes = new Set(worldlinePaymentMethods.map((method) => String(method.code || '').trim().toLowerCase()))
  const filteredBasePaymentMethods = basePaymentMethods.filter((method) => {
    const provider = String(method.providerCode || '').trim().toLowerCase().replace(/[\s-]+/g, '_')
    if (provider !== 'worldline') return true
    return worldlineDiscoveryOk && worldlineAvailableCodes.has(String(method.code || '').trim().toLowerCase())
  })
  const paymentMethodsByCode = new Map(filteredBasePaymentMethods.map((method) => [method.code, method]))
  for (const method of worldlinePaymentMethods) paymentMethodsByCode.set(method.code, method)
  const paymentMethods = Array.from(paymentMethodsByCode.values())
    .sort((a, b) => a.priority - b.priority || a.code.localeCompare(b.code))
  const configuredLocales = enabledLocales(settings, resolvedThemePayload, settingsLocale(settings))
  const requestedLocale = localeCode(query.locale || settingsLocale(settings))
  const locale = configuredLocales.includes(requestedLocale) ? requestedLocale : configuredLocales[0]
  const activeOrder = normalizeOrder(orderPayload)

  return {
    apiVersion: 'pmd-customer-bootstrap-v2',
    tenant: { id: host.split('.')[0] || 'default', slug: host.split('.')[0] || 'default', host },
    restaurant: { ...restaurantInfo, locale },
    theme,
    locales: { defaultLocale: locale, enabledLocales: configuredLocales },
    socialLinks: normalizeSocial(settings, resolvedThemePayload),
    features: normalizeFeatures(settings, resolvedThemePayload),
    tax: normalizeTax(taxApiPayload || taxLegacyPayload || settings),
    tips: normalizeTips(tipApiPayload || settings),
    serviceCharge: normalizeServiceCharge(settings, resolvedThemePayload),
    table,
    menu,
    setup: {
      frontendConfigured,
      status: setupStatus,
    },
    payments: paymentMethods,
    activeOrder: table.valid && activeOrder
      && (activeOrder.status === 'draft' || activeOrder.totals.remainingAmount > 0)
      && (activeOrder.canShowToNewDevice || activeOrder.status === 'draft')
      ? activeOrder
      : null,
  }
}

export function previewBootstrap(themeId: ThemeId, host = 'preview.paymydine.local'): CustomerBootstrap {
  return createMockBootstrap(themeId, host)
}
